 p=binddir(i)
 (p/'named.conf').write_text(f'options {{ {opts} }};\\nzone \"{zone}\" {{ type master; file \"/etc/bind/db.{zone}\"; }};\\n')
 lines=['"'$TTL 3600'"',f'@ IN SOA ns.{zone}. hostmaster.{zone}. ( 1 3600 900 604800 300 )',f'@ IN NS ns.{zone}.',f'ns IN A {ips[i]}']
 for name,pc in records.items():
  if name.endswith('.'+zone): lines.append(f'{name}. IN A {ips[pc]}')
 for name,target in mx.items():
  if name.endswith('.'+zone): lines.append(f'{name}. IN MX 10 {target}.')
 (p/f'db.{zone}').write_text('\\n'.join(lines)+'\\n')
servers={1,2,*zones.values()}
for i in range(1,61):
 with Path(f'pc{i}.startup').open('a') as f:
  f.write(f'\\n# DNS\\necho \"nameserver {ips[2]}\" > /etc/resolv.conf\\n')
