/usr/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
import re, ipaddress
zones={'com':3,'net':4,'edu':5,'it':6,'org':8,'io':9,'gov':10,'info':12}
root=Path('pc1/etc/bind/db.root').read_text()
for z,i in zones.items():
 ip=re.search(r'inet ([\\d.]+)/',Path(f'pc{i}.startup').read_text()).group(1)
 assert f'{z}. IN NS ns.{z}.' in root and f'ns.{z}. IN A {ip}' in root
 text=Path(f'pc{i}/etc/bind/db.{z}').read_text()
 assert f'ns IN A {ip}' in text and f'@ IN NS ns.{z}.' in text
for i in range(1,61): assert 'nameserver 10.16.1.12' in Path(f'pc{i}.startup').read_text()
for i in range(1,13):
 s=Path(f'r{i}.startup').read_text()
 direct={ipaddress.ip_interface(x).network for x in re.findall(r'inet ([\\d.]+/\\d+)',s)}
 routes={ipaddress.ip_network(x) for x in re.findall(r'ip route replace (10\\.16\\.\\d+\\.0/24)',s)}
 assert all(ipaddress.ip_network(f'10.16.{n}.0/24') in direct|routes for n in range(1,16)),f'r{i} missing route'
print('Static checks passed: delegations, glue, 60 resolver settings, and router LAN routes.')
PY"

